use v5.42;
use strict;
use warnings;
use JSON::PP ();
use Digest::SHA 'sha256_hex';
use File::Basename 'dirname';
use File::Temp 'tempfile';
use Cwd 'abs_path';
use Time::HiRes qw(clock_gettime CLOCK_MONOTONIC);
use IPC::Open3 'open3';
use lib 'bench/lib';
use Wump::BenchMatrix 'validate_result';
@ARGV==5 or die 'usage: capture-yield.pl BEFORE_PERL AFTER_PERL BEFORE_C AFTER_C METADATA';
my ($old_perl,$new_perl,$old_c,$new_c,$metadata)=@ARGV;
sub contents ($path) {open my $in,'<',$path or die "$path: $!"; local $/; my $text=<$in>; close $in or die $!; return $text}
sub capture (@command) {
	my ($errors)=tempfile(UNLINK=>1);
	my ($input,$output);
	my $pid=open3($input,$output,'>&'.fileno($errors),@command);
	close $input or die $!;
	my $text=do {local $/; <$output>}; close $output or die $!;
	waitpid($pid,0)==$pid or die $!; my $status=$?;
	seek $errors,0,0 or die $!;
	my $diagnostics=do {local $/; <$errors>};
	!$status && !length($diagnostics) or die "failed ($status): @command\n$diagnostics";
	return $text;
}
for my $key(qw(PERL5OPT PERL5LIB PERLLIB PERL_UNICODE PERL_HASH_SEED PERL_PERTURB_KEYS PERLIO PERL_DESTRUCT_LEVEL)) {delete $ENV{$key}}
local $ENV{LC_ALL}='C'; local $ENV{LANG}='C'; local $ENV{TZ}='UTC';
capture('git','status','--porcelain') eq '' or die 'dirty source';
my $revision=capture('git','rev-parse','HEAD'); chomp $revision;
my $affinity=contents('/proc/self/status'); $affinity=~/^Cpus_allowed_list:\s*(\S+)/m or die 'affinity';
$1 eq '0,2,4,6' or die 'wrong CPU mask';
my @sources=qw(runtime/src/sched.c runtime/src/internal.h runtime/include/wump.h tests/test_scheduler.c bench/matrix-worker.pl bench/lib/Wump/BenchMatrix.pm perl/lib/Wump.pm);
my $root=dirname($old_c);
my $worker="$root/yield-worker.c";
my @archives=('/home/marcus/projects/wump/master/build/checkpoint-callee/integration/libwump.a',"$root/integration/libwump.a");
my %hashes=map {$_=>sha256_hex(contents($_))} ($old_perl,$new_perl,$old_c,$new_c,$worker,@archives,@sources);
my %binaries;
for my $pair ([before_perl=>$old_perl],[after_perl=>$new_perl],[before_c=>$old_c],[after_c=>$new_c]) {
	my ($role,$path)=@$pair;
	my $value={path=>abs_path($path),sha256=>$hashes{$path}};
	if ($role=~/_perl\z/) {
		$value->{config}=JSON::PP::decode_json(capture($path,'-I'.dirname($path).'/lib','-MConfig','-MJSON::PP','-e',q{print JSON::PP::encode_json({map {$_=>$Config::Config{$_}//''} qw(version archname cc gccversion ccflags ldflags lddlflags optimize usemultiplicity useithreads use64bitall)})}));
	}
	$binaries{$role}=$value;
}
JSON::PP->new->canonical->encode($binaries{before_perl}{config}) eq JSON::PP->new->canonical->encode($binaries{after_perl}{config}) or die 'config mismatch';
my $compiler=capture('cc','--version');
my $cpu=contents('/proc/cpuinfo'); $cpu=~/^model name\s*:\s*(.+)$/m or die 'CPU'; my $cpu_model=$1;
my $kernel=capture('uname','-srmo'); chomp $kernel;
my $sequence=0; my $n=2000000;
for my $run (1..7) {
	my @surfaces=$run%2 ? ('c','perl') : ('perl','c');
	my @slots=(1,2,4); my $offset=($run-1)%3;
	@slots=(@slots[$offset..$#slots],@slots[0..$offset-1]);
	for my $surface (@surfaces) {
		for my $slots (@slots) {
			for my $role ($run%2 ? ('before','after') : ('after','before')) {
				my $binary=$binaries{"${role}_$surface"}{path};
				local $ENV{WUMP_MATRIX_MODE}='wump'; local $ENV{WUMPPROCS}=$slots; local $ENV{WUMP_MATRIX_SLOTS}=$slots;
				my @command=$surface eq 'c' ? ($binary,$n,$slots)
					: ($binary,'-I'.dirname($binary).'/lib','-Iperl/lib','bench/matrix-worker.pl','yield',$n,8);
				my $start=clock_gettime(CLOCK_MONOTONIC);
				my $v=JSON::PP::decode_json(capture('taskset','-c','0,2,4,6','timeout','90s',@command));
				my $elapsed=clock_gettime(CLOCK_MONOTONIC)-$start;
				if ($surface eq 'perl') {
					validate_result($v,'yield',"wump-$slots",$n,8);
					join(',',@{$v->{native_ops}}) eq 'wumpact,wumpchan,wumpyield'
						&& join(',',@{$v->{native_methods}}) eq 'Wump::Channel::close,Wump::Channel::recv,Wump::Channel::send' or die 'lost native bindings';
				} else {
					$v->{operation} eq 'yield' && $v->{iterations}==$n && $v->{units}==$n
						&& $v->{completed}==$n && $v->{slots}==$slots or die 'bad C completion';
				}
				$v->{status} eq 'ok' && $v->{wall_seconds}>0 && $v->{wall_seconds}<=$elapsed or die 'bad timing';
				print JSON::PP->new->canonical->encode({%$v,surface=>$surface,role=>$role,run=>$run,
					sequence=>++$sequence,process_seconds=>$elapsed}),"\n";
			}
		}
	}
}
$sequence==84 or die 'incomplete capture';
for my $path(keys %hashes) {sha256_hex(contents($path)) eq $hashes{$path} or die "changed $path"}
capture('git','status','--porcelain') eq '' or die 'source changed';
open my $out,'>',"$metadata.tmp" or die $!;
print {$out} JSON::PP->new->canonical->pretty->encode({source_revision=>$revision,baseline_revision=>q{ba5a73a30734af0cfbd36ed44a768df75b88e9dd},source_dirty=>JSON::PP::false,
	binaries=>\%binaries,sha256=>\%hashes,cpu_model=>$cpu_model,kernel=>$kernel,affinity=>'0,2,4,6',
	runs=>7,iterations=>$n,samples=>$sequence,c_compiler=>$compiler,
	c_flags=>['-O2','-g','-std=c11','-Wall','-Wextra','-Werror','-pthread','-Iruntime/include'],c_link_flags=>['-pthread','-lm'],
	worker_source=>contents($worker),runner_source=>contents(__FILE__)}) or die $!;
close $out or die $!;
rename "$metadata.tmp",$metadata or die $!;

