#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include "wump.h"

typedef struct sample {
	unsigned iterations;
	int slots;
	volatile uint64_t completed;
	double seconds;
} sample;

static double now(void) {
	struct timespec value;
	if (clock_gettime(CLOCK_MONOTONIC, &value)) { perror("clock_gettime"); exit(1); }
	return (double)value.tv_sec + (double)value.tv_nsec / 1e9;
}
static unsigned number(const char *text) {
	char *end;
	errno = 0;
	unsigned long value = strtoul(text, &end, 10);
	if (errno || !*text || *end || value < 1 || value > 2000000) {
		fprintf(stderr, "invalid positive integer\n"); exit(1);
	}
	return (unsigned)value;
}
static void run_sample(void *arg) {
	sample *value = arg;
	value->slots = wump_nprocs();
	double start = now();
	for (unsigned i = 0; i < value->iterations; i++) {
		wump_yield();
		value->completed++;
	}
	value->seconds = now() - start;
}
int main(int argc, char **argv) {
	if (argc != 3) { fprintf(stderr, "usage: yield-worker ITERATIONS SLOTS\n"); return 1; }
	sample value = { .iterations = number(argv[1]) };
	unsigned slots = number(argv[2]);
	if (slots != 1 && slots != 2 && slots != 4) { fprintf(stderr, "invalid slots\n"); return 1; }
	if (wump_run(run_sample, &value, (int)slots)) { perror("wump_run"); return 1; }
	if (value.completed != value.iterations || value.slots != (int)slots || value.seconds <= 0) return 1;
	printf("{\"status\":\"ok\",\"operation\":\"yield\",\"iterations\":%u,\"slots\":%d,\"units\":%u,\"completed\":%llu,\"wall_seconds\":%.17g}\n",
		value.iterations, value.slots, value.iterations, (unsigned long long)value.completed, value.seconds);
	return 0;
}
